function initBatchModal() {
  // Show embedded batch in list
  const list = document.getElementById('batchList');
  list.innerHTML = '';

  const opt = document.createElement('div');
  opt.className = 'batch-opt selected';
  opt.innerHTML = `
    <div class="batch-opt-ico">📦</div>
    <div style="flex:1">
      <div class="batch-opt-name">Batch-256 <span style="font-size:10px;color:#059669;font-weight:600">⬤ Pre-loaded</span></div>
      <div class="batch-opt-desc">Flickr 8K-Hindi · 40 Epochs · 127 Batches · Best checkpoint: Epoch 17</div>
    </div>
    <div class="batch-opt-check">✓</div>`;
  opt.dataset.batchId = 'embedded';
  list.appendChild(opt);

  // File validation panel (shown after user picks files)
  updateFileValidation(null);
}

function updateFileValidation(fileMap) {
  const wrap = document.getElementById('fileValidationWrap');
  if (!fileMap) {
    wrap.innerHTML = `<div style="font-size:12px;color:var(--text3);padding:4px 0">
      📂 Or load a new batch folder — select all 5 files inside it using the picker below.
    </div>`;
    return;
  }
  const checks = validateFiles(fileMap);
  const allOk  = checks.every(c => c.present);
  wrap.innerHTML = `
    <div style="font-size:11px;font-weight:700;color:${allOk?'var(--green)':'var(--orange)'};margin-bottom:6px">
      ${allOk ? '✅ All required files detected' : '⚠️ Some files missing'}
    </div>
    <div class="batch-files-list">
      ${checks.map(c=>`<span class="batch-file-tag ${c.present?'':'missing'}">${c.present?'✓':'✗'} ${c.name}</span>`).join('')}
    </div>`;
}

function openFilePicker() {
  if (!filePicker) {
    filePicker = document.createElement('input');
    filePicker.type     = 'file';
    filePicker.multiple = true;
    filePicker.accept   = '.xlsx,.txt';
    filePicker.addEventListener('change', onFilesSelected);
  }
  filePicker.value = '';
  filePicker.click();
}
window.openFilePicker = openFilePicker;

let pendingFileMap = null;

function onFilesSelected(e) {
  const files = e.target.files;
  if (!files.length) return;

  const map = buildFileMap(files);
  pendingFileMap = map;
  updateFileValidation(map);

  // Infer batch name from a file path hint (modern browsers expose webkitRelativePath)
  let batchName = 'Custom Batch';
  for (const f of files) {
    if (f.webkitRelativePath) {
      batchName = f.webkitRelativePath.split('/')[0] || batchName;
      break;
    }
  }

  // Add to batch list if all present
  const checks = validateFiles(map);
  const allOk  = checks.every(c => c.present);
  if (allOk) {
    const list = document.getElementById('batchList');
    // Remove existing custom entries
    list.querySelectorAll('[data-batch-id=custom]').forEach(el => el.remove());
    list.querySelectorAll('.batch-opt').forEach(o => o.classList.remove('selected'));
    list.querySelectorAll('.batch-opt-check').forEach(ch => ch.style.display='none');

    const opt = document.createElement('div');
    opt.className = 'batch-opt selected';
    opt.dataset.batchId = 'custom';
    opt.innerHTML = `
      <div class="batch-opt-ico">📁</div>
      <div style="flex:1">
        <div class="batch-opt-name">${batchName} <span style="font-size:10px;color:var(--blue);font-weight:600">⬤ From files</span></div>
        <div class="batch-opt-desc">${checks.length} / ${checks.length} required files detected</div>
      </div>
      <div class="batch-opt-check" style="display:block">✓</div>`;
    list.appendChild(opt);
  }

  const btn = document.getElementById('btnLoadBatch');
  if (btn) btn.disabled = !allOk;
}

async function loadBatch() {
  const btn    = document.getElementById('btnLoadBatch');
  const state  = document.getElementById('loadState');
  btn.disabled = true;

  // Determine which batch to load
  const selected = document.querySelector('.batch-opt.selected');
  const batchId  = selected?.dataset.batchId || 'embedded';

  if (batchId === 'embedded') {
    D = EMBEDDED_BATCH;
    finishLoad('Batch-256');
    return;
  }

  // Parse custom files
  if (!pendingFileMap) { btn.disabled = false; return; }

  state.style.display = 'flex';
  state.querySelector('.load-msg').textContent = 'Parsing Excel files…';

  try {
    const batchName = selected?.querySelector('.batch-opt-name')?.textContent?.trim()
                                .replace(/⬤.*/, '').trim() || 'Custom Batch';
    state.querySelector('.load-msg').textContent = 'Parsing generated predictions…';
    D = await parseFilesToDataset(pendingFileMap, batchName);
    finishLoad(batchName);
  } catch (err) {
    console.error(err);
    state.style.display = 'none';
    alert('Error parsing files:\n' + err.message);
    btn.disabled = false;
  }
}
window.loadBatch = loadBatch;

function finishLoad(batchName) {
  document.getElementById('loadState').style.display  = 'none';
  document.getElementById('batchOverlay').style.display = 'none';
  document.getElementById('batchLabel').textContent =
    `${D.batchName} · Flickr 8K-Hindi · ${D.training.length} Epochs`;
  document.getElementById('checkpointBadge').textContent =
    `Epoch ${D.testResult.epoch} — Best Checkpoint`;
  document.getElementById('btnLoadBatch').disabled = false;
  pendingFileMap = null;
  renderAll();
}

